-- Platform-owner-managed public marketing pages (TEST first).
create table if not exists public.platform_public_pages (
  slug text primary key check (slug in ('how-it-works','examples')),
  title text not null,
  draft_content jsonb not null default '{}'::jsonb,
  published_content jsonb not null default '{}'::jsonb,
  is_published boolean not null default false,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id),
  published_at timestamptz,
  published_by uuid references auth.users(id)
);
alter table public.platform_public_pages enable row level security;
revoke all on public.platform_public_pages from anon, authenticated;

