create or replace function public.platform_owner_get_public_pages()
returns table(slug text,title text,draft_content jsonb,published_content jsonb,is_published boolean,updated_at timestamptz,published_at timestamptz)
language plpgsql security definer set search_path to 'public','auth'
as $$
begin
 if auth.uid() is null or not exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active') then raise exception 'Active platform owner access required'; end if;
 return query select p.slug,p.title,p.draft_content,p.published_content,p.is_published,p.updated_at,p.published_at from public.platform_public_pages p order by p.slug;
end; $$;

create or replace function public.platform_owner_save_public_page(p_slug text,p_title text,p_content jsonb)
returns jsonb language plpgsql security definer set search_path to 'public','auth'
as $$
declare result_row public.platform_public_pages;
begin
 if auth.uid() is null or not exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active') then raise exception 'Active platform owner access required'; end if;
 if p_slug not in ('how-it-works','examples') then raise exception 'Unsupported public page'; end if;
 if length(trim(coalesce(p_title,''))) not between 1 and 120 then raise exception 'Page title is required and must be 120 characters or fewer'; end if;
 if p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>500000 then raise exception 'Page content must be a JSON object under 500 KB'; end if;
 update public.platform_public_pages set title=trim(p_title),draft_content=p_content,updated_at=now(),updated_by=auth.uid() where slug=p_slug returning * into result_row;
 if not found then raise exception 'Public page not found'; end if;
 return jsonb_build_object('slug',result_row.slug,'title',result_row.title,'updated_at',result_row.updated_at);
end; $$;

create or replace function public.platform_owner_publish_public_page(p_slug text)
returns jsonb language plpgsql security definer set search_path to 'public','auth'
as $$
declare result_row public.platform_public_pages;
begin
 if auth.uid() is null or not exists(select 1 from public.platform_memberships pm where pm.user_id=auth.uid() and pm.status='active') then raise exception 'Active platform owner access required'; end if;
 if p_slug not in ('how-it-works','examples') then raise exception 'Unsupported public page'; end if;
 update public.platform_public_pages set published_content=draft_content,is_published=true,published_at=now(),published_by=auth.uid(),updated_at=now() where slug=p_slug returning * into result_row;
 if not found then raise exception 'Public page not found'; end if;
 return jsonb_build_object('slug',result_row.slug,'is_published',result_row.is_published,'published_at',result_row.published_at);
end; $$;

create or replace function public.platform_public_page_get(p_slug text)
returns jsonb language sql stable security definer set search_path to 'public','auth'
as $$ select case when p.is_published then p.published_content else null end from public.platform_public_pages p where p.slug in ('how-it-works','examples') and p.slug=p_slug limit 1; $$;

revoke all on function public.platform_owner_get_public_pages() from public,anon;
revoke all on function public.platform_owner_save_public_page(text,text,jsonb) from public,anon;
revoke all on function public.platform_owner_publish_public_page(text) from public,anon;
revoke all on function public.platform_public_page_get(text) from public;
grant execute on function public.platform_owner_get_public_pages() to authenticated;
grant execute on function public.platform_owner_save_public_page(text,text,jsonb) to authenticated;
grant execute on function public.platform_owner_publish_public_page(text) to authenticated;
grant execute on function public.platform_public_page_get(text) to anon,authenticated;
